document.addEventListener('DOMContentLoaded',()=>{const f=document.getElementById('f'),out=document.getElementById('out');f.addEventListener('submit',async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f));const r=await fetch('/api/member-applications',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});out.textContent=JSON.stringify(await r.json(),null,2)})});
